1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.util.E164PhoneNumbers;
12	import org.springframework.samples.petclinic.util.IdentityKeyUtils;
13	
14	import java.time.LocalDate;
15	import java.time.Month;
16	import java.time.Period;
17	import java.util.Collection;
18	import java.util.List;
19	import java.util.Map;
20	import java.util.Set;
21	
22	/**
23	 * Maps Owner & OwnerDto using Mapstruct
24	 */
25	@Mapper(uses = PetMapper.class)
26	public interface OwnerMapper {
27	
28	    @Mapping(target = "displayName",
29	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
30	    @Mapping(target = "initials",
31	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
32	            + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
33	    @Mapping(target = "membershipPoints",
34	        expression = "java(toMembershipPoints(owner))")
35	    @Mapping(target = "membershipLevel",
36	        expression = "java(toMembershipLevel(owner))")
37	    @Mapping(target = "locality",
38	        expression = "java(toLocality(owner))")
39	    @Mapping(target = "ownerSegment",
40	        expression = "java(toOwnerSegment(owner))")
41	    @Mapping(target = "timezone",
42	        expression = "java(toTimezone(owner))")
43	    @Mapping(target = "contactPreference",
44	        expression = "java(toContactPreference(owner))")
45	    @Mapping(target = "identityKey",
46	        expression = "java(toIdentityKey(owner))")
47	    @Mapping(target = "ageBand",
48	        expression = "java(toAgeBand(owner))")
49	    @Mapping(target = "telephoneDisplay",
50	        expression = "java(toTelephoneDisplay(owner))")
51	    @Mapping(target = "salutation",
52	        expression = "java(toSalutation(owner))")
53	    @Mapping(target = "fiscalYear",
54	        expression = "java(toFiscalYear(owner))")
55	    @Mapping(target = "selfLink",
56	        expression = "java(toSelfLink(owner))")
57	    @Mapping(target = "riskFlag",
58	        expression = "java(toRiskFlag(owner))")
59	    OwnerDto toOwnerDto(Owner owner);
60	
61	    /**
62	     * The second-level labels of the known disposable-email providers (the create endpoint's
63	     * disposable-domain blocklist, keyed by the label immediately before the final TLD). A stored
64	     * email can never carry a whole blocklisted domain (the create endpoint rejects those with a 400),
65	     * so this drives the softer "disposable-adjacent" signal instead — a domain that merely shares a
66	     * disposable provider's base label, such as a subdomain of it or the same base with a different TLD.
67	     */
68	    Set<String> DISPOSABLE_EMAIL_BASE_LABELS = Set.of("mailinator", "tempmail", "guerrillamail");
69	
70	    /**
71	     * Derive an owner's risk flag: {@code true} when the owner warrants a manual risk review, defined
72	     * as the logical OR of three conditions — the owner is a possible duplicate
73	     * ({@code possibleDuplicate} is true), the owner's email domain is disposable-adjacent (see
74	     * {@link #hasDisposableAdjacentEmail(Owner)}), or the owner's city is over its soft capacity
75	     * ({@code capacityWarning} is true). Otherwise {@code false}. Derived at read time.
76	     */
77	    default Boolean toRiskFlag(Owner owner) {
78	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
79	            || Boolean.TRUE.equals(owner.getCapacityWarning())
80	            || hasDisposableAdjacentEmail(owner);
81	    }
82	
83	    /**
84	     * Whether the owner's email domain is disposable-adjacent: a domain that is not itself a
85	     * whole-blocklisted disposable domain (those are rejected at creation) but shares a known
86	     * disposable provider's second-level label — i.e. one of the domain's dot-separated labels equals a
87	     * label in {@link #DISPOSABLE_EMAIL_BASE_LABELS}. This catches subdomains of a disposable provider
88	     * (e.g. {@code sub.mailinator.com}) and the same base under a different TLD (e.g.
89	     * {@code mailinator.net}), while a merely similar label (e.g. {@code mymailinator.com}) is not
90	     * matched. Returns {@code false} when the owner has no email or the value carries no domain.
91	     */
92	    default boolean hasDisposableAdjacentEmail(Owner owner) {
93	        if (!hasEmail(owner)) {
94	            return false;
95	        }
96	        String email = owner.getEmail();
97	        int at = email.lastIndexOf('@');
98	        if (at < 0 || at == email.length() - 1) {
99	            return false;
100	        }
101	        String domain = email.substring(at + 1).toLowerCase();
102	        for (String label : domain.split("\\.")) {
103	            if (DISPOSABLE_EMAIL_BASE_LABELS.contains(label)) {
104	                return true;
105	            }
106	        }
107	        return false;
108	    }
109	
110	    /**
111	     * Derive an owner's canonical self link: the resource path {@code '/api/owners/<id>'} where
112	     * {@code <id>} is the owner's id. Returns {@code null} when the owner has no id yet (the field is
113	     * then absent from the DTO).
114	     */
115	    default String toSelfLink(Owner owner) {
116	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
117	    }
118	
119	    /**
120	     * The fiscal year that the given date falls in, where the fiscal year starts on 1 July and is
121	     * identified by the calendar year in which it ends. A date on or after 1 July belongs to the
122	     * fiscal year ending in the following calendar year (e.g. 2026-08-01 -&gt; 2027), while a date
123	     * before 1 July belongs to the fiscal year ending in the same calendar year (e.g. 2026-03-01 -&gt;
124	     * 2026). This is the single source of truth for the fiscal year used both when the create endpoint
125	     * bakes the FY segment into the member id (see {@code OwnerRestControllerV1.memberIdFor}) and when
126	     * the DTO's {@code fiscalYear} falls back to the registration date for a legacy record.
127	     *
128	     * @param date the date to resolve, on a business day
129	     * @return the calendar year in which that date's fiscal year ends
130	     */
131	    static int fiscalYear(LocalDate date) {
132	        int year = date.getYear();
133	        return date.getMonthValue() >= Month.JULY.getValue() ? year + 1 : year;
134	    }
135	
136	    /**
137	     * Derive an owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the two-digit fiscal-year
138	     * segment carried by the {@code memberId} (see {@link #memberIdBase(String)}), e.g. {@code 'FY27'}.
139	     * The fiscal year therefore moves with the owner's member id. When an owner has no (well-formed)
140	     * member id yet (e.g. legacy records) it falls back to deriving the fiscal year directly from the
141	     * business-day-adjusted {@code registrationDate} (see {@link #fiscalYear(LocalDate)}), and returns
142	     * {@code null} when neither is present (the field is then absent from the DTO).
143	     */
144	    default String toFiscalYear(Owner owner) {
145	        String base = memberIdBase(owner.getMemberId());
146	        if (base != null) {
147	            return "FY" + memberIdFyDigits(base);
148	        }
149	        LocalDate registrationDate = owner.getRegistrationDate();
150	        return registrationDate == null ? null : String.format("FY%02d", fiscalYear(registrationDate) % 100);
151	    }
152	
153	    /**
154	     * Derive an owner's salutation: the {@code title}, a single space, and the {@code lastName}
155	     * (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the salutation is
156	     * just the last name.
157	     */
158	    default String toSalutation(Owner owner) {
159	        String lastName = owner.getLastName();
160	        String title = owner.getTitle();
161	        if (title == null || title.isBlank()) {
162	            return lastName;
163	        }
164	        return title + " " + lastName;
165	    }
166	
167	    /**
168	     * Derive an owner's age band from the {@code birthDate} relative to the {@code registrationDate}:
169	     * 'MINOR' when under 18, 'ADULT' when 18 to 64, and 'SENIOR' when 65 or older. Returns
170	     * {@code null} when no birth date was supplied (the band is then absent from the DTO). When the
171	     * registration date is missing (e.g. legacy records) the current date is used as the reference.
172	     */
173	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
174	        LocalDate birthDate = owner.getBirthDate();
175	        if (birthDate == null) {
176	            return null;
177	        }
178	        LocalDate reference = owner.getRegistrationDate() != null
179	            ? owner.getRegistrationDate() : LocalDate.now();
180	        int age = Period.between(birthDate, reference).getYears();
181	        if (age < 18) {
182	            return OwnerDto.AgeBandEnum.MINOR;
183	        }
184	        if (age < 65) {
185	            return OwnerDto.AgeBandEnum.ADULT;
186	        }
187	        return OwnerDto.AgeBandEnum.SENIOR;
188	    }
189	
190	    /**
191	     * Format an owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
192	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
193	     * The raw {@code telephone} property is left untouched in E.164 form. Returns the value unchanged
194	     * when it is {@code null} or not in {@code '+'}-prefixed E.164 form.
195	     *
196	     * <p>The recognized dialling codes come from {@link E164PhoneNumbers}, the same table the create
197	     * endpoint validates against, so the two paths cannot diverge. When a number carries no recognized
198	     * code, a two-digit country code is assumed (the most common length).
199	     */
200	    default String toTelephoneDisplay(Owner owner) {
201	        String telephone = owner.getTelephone();
202	        if (telephone == null || !telephone.startsWith("+")) {
203	            return telephone;
204	        }
205	        String digits = telephone.substring(1);
206	        String code = E164PhoneNumbers.countryCode(digits)
207	            .filter(c -> digits.length() > c.length())
208	            .orElse(digits.length() > 2 ? digits.substring(0, 2) : digits);
209	        String national = digits.substring(code.length());
210	        StringBuilder sb = new StringBuilder("+").append(code);
211	        for (int i = 0; i < national.length(); i += 3) {
212	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
213	        }
214	        return sb.toString();
215	    }
216	
217	    /**
218	     * The fixed trailing-segment widths of a member id base {@code '<REGION><FY><HASH8><CHK>'}: FY is 2
219	     * digits, HASH8 is 8 hex characters and CHK is 1 digit, so the last {@link #MEMBER_ID_SUFFIX_WIDTH}
220	     * characters are the {@code <FY><HASH8><CHK>} suffix and REGION is the variable-width remainder in
221	     * front of it. This is the single place the layout is encoded; the position arithmetic in
222	     * {@link #memberIdRegion(String)} and {@link #memberIdFyDigits(String)} derives from these, and it
223	     * must stay in step with how {@code OwnerRestControllerV1.memberIdFor} assembles the id.
224	     */
225	    int FY_WIDTH = 2;
226	    int HASH8_WIDTH = 8;
227	    int CHK_WIDTH = 1;
228	    int MEMBER_ID_SUFFIX_WIDTH = FY_WIDTH + HASH8_WIDTH + CHK_WIDTH;
229	
230	    /**
231	     * The {@code '<REGION><FY><HASH8><CHK>'} base of a member id, dropping any {@code '-<n>'} collision
232	     * suffix, or {@code null} when the owner has no (well-formed) member id yet — i.e. one long enough to
233	     * carry a non-empty REGION in front of the fixed {@link #MEMBER_ID_SUFFIX_WIDTH}-character suffix.
234	     * Use {@link #memberIdRegion(String)} and {@link #memberIdFyDigits(String)} to decode its segments.
235	     */
236	    private static String memberIdBase(String memberId) {
237	        if (memberId == null) {
238	            return null;
239	        }
240	        int dash = memberId.indexOf('-');
241	        String base = dash >= 0 ? memberId.substring(0, dash) : memberId;
242	        return base.length() > MEMBER_ID_SUFFIX_WIDTH ? base : null;
243	    }
244	
245	    /**
246	     * The leading {@code <REGION>} segment of a (non-null, well-formed) member id base: everything
247	     * before the fixed trailing {@code <FY><HASH8><CHK>} suffix.
248	     */
249	    private static String memberIdRegion(String base) {
250	        return base.substring(0, base.length() - MEMBER_ID_SUFFIX_WIDTH);
251	    }
252	
253	    /**
254	     * The two-digit {@code <FY>} segment of a (non-null, well-formed) member id base: the characters
255	     * immediately preceding the trailing HASH8 and CHK segments.
256	     */
257	    private static String memberIdFyDigits(String base) {
258	        int fyEnd = base.length() - HASH8_WIDTH - CHK_WIDTH;
259	        return base.substring(fyEnd - FY_WIDTH, fyEnd);
260	    }
261	
262	    /**
263	     * Derive an owner's duplicate-detection identity key: the lower-case SHA-256 hex digest (64
264	     * characters) of the normalized E.164 telephone, the lower-cased email (empty when none) and the
265	     * American Soundex code of the last name, joined with {@code '|'}. Two owners are duplicates only
266	     * when their whole identity keys are equal.
267	     *
268	     * <p>This is the single source of truth for the key: it is both returned on the DTO and used by
269	     * the create endpoint's 409 duplicate check, so the value clients see is exactly the value that
270	     * governs rejection. The "email present" rule reuses {@link #hasEmail(Owner)}, and the Soundex and
271	     * hashing come from {@link IdentityKeyUtils}, the same helpers the soft-match uses.
272	     */
273	    default String toIdentityKey(Owner owner) {
274	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
275	        String email = hasEmail(owner) ? owner.getEmail() : "";
276	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
277	        return IdentityKeyUtils.sha256Hex(telephone + "|" + email + "|" + soundex);
278	    }
279	
280	    /**
281	     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
282	     * for the "is an email present" rule shared by the derived fields below.
283	     */
284	    default boolean hasEmail(Owner owner) {
285	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
286	    }
287	
288	    /**
289	     * Derive an owner's preferred contact channel: 'EMAIL' when an email address is present,
290	     * otherwise 'PHONE'.
291	     */
292	    default String toContactPreference(Owner owner) {
293	        return hasEmail(owner) ? "EMAIL" : "PHONE";
294	    }
295	
296	    /**
297	     * Derive an owner's membership points: start at 0; add 2 when an email address is present; add 1
298	     * when the owner has no namesakes (namesakeCount is 0); add 2 when the owner belongs to a
299	     * household of 3 or more (see {@link #hasHouseholdBonus(Owner)}); add 3 when the owner's tenure
300	     * is at least one elapsed fiscal year (see {@link #hasTenureBonus(Owner)}). Because a newly
301	     * created owner has zero tenure it never earns the tenure points, so a new owner with an email
302	     * and no namesakes in a single-member household scores 3 points.
303	     */
304	    default Integer toMembershipPoints(Owner owner) {
305	        int points = 0;
306	        if (hasEmail(owner)) {
307	            points += 2;
308	        }
309	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
310	        if (noNamesakes) {
311	            points += 1;
312	        }
313	        if (hasHouseholdBonus(owner)) {
314	            points += 2;
315	        }
316	        if (hasTenureBonus(owner)) {
317	            points += 3;
318	        }
319	        return points;
320	    }
321	
322	    /**
323	     * Whether the owner belongs to a household of 3 or more members. The household size is the count
324	     * of owners sharing the owner's household id, frozen at creation (see the create endpoint).
325	     * Returns {@code false} when no household size is present (e.g. legacy records).
326	     */
327	    default boolean hasHouseholdBonus(Owner owner) {
328	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
329	    }
330	
331	    /**
332	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
333	     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
334	     * or more.
335	     *
336	     * <p>The level is then capped at the owner's {@code membershipLevelCap} when one is present: a new
337	     * owner's membership level cannot exceed one above the current maximum membership level among their
338	     * existing household members, so the cap (frozen at creation, see the create endpoint) is the
339	     * ceiling applied here. When no cap is present (e.g. an owner created with no existing household
340	     * member, or a legacy record) the uncapped level stands.
341	     */
342	    default Integer toMembershipLevel(Owner owner) {
343	        int level = uncappedMembershipLevel(owner);
344	        Integer cap = owner.getMembershipLevelCap();
345	        if (cap != null && level > cap) {
346	            return cap;
347	        }
348	        return level;
349	    }
350	
351	    /**
352	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
353	     * {@link #toMembershipPoints(Owner)}) before any household ceiling is applied: level 1 for 0-1
354	     * points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
355	     */
356	    default Integer uncappedMembershipLevel(Owner owner) {
357	        int points = toMembershipPoints(owner);
358	        if (points <= 1) {
359	            return 1;
360	        }
361	        if (points <= 3) {
362	            return 2;
363	        }
364	        if (points <= 5) {
365	            return 3;
366	        }
367	        return 4;
368	    }
369	
370	    /**
371	     * Whether the owner's tenure is at least one elapsed fiscal year, i.e. the fiscal year of the
372	     * current date is later than the fiscal year of the {@code registrationDate} (fiscal years start
373	     * on 1 July; see {@link #fiscalYear(LocalDate)}). A brand-new owner (registered in the current
374	     * fiscal year) has zero elapsed fiscal years and so never qualifies. Returns {@code false} when
375	     * no registration date is present.
376	     */
377	    default boolean hasTenureBonus(Owner owner) {
378	        LocalDate registrationDate = owner.getRegistrationDate();
379	        if (registrationDate == null) {
380	            return false;
381	        }
382	        return fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) >= 1;
383	    }
384	
385	    /**
386	     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
387	     */
388	    Map<String, String> CITY_REGION = Map.of(
389	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
390	
391	    /**
392	     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
393	     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
394	     * inclusive.
395	     */
396	    Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
397	        "NSW", new int[] {2000, 2099},
398	        "VIC", new int[] {3000, 3099},
399	        "QLD", new int[] {4000, 4099});
400	
401	    /**
402	     * Derive an owner's locality (region) from the region-and-hash member id: the leading
403	     * {@code <REGION>} segment of the {@code memberId}, i.e. everything before its trailing FY, HASH8
404	     * and CHK segments (see {@link #memberIdBase(String)}). Since the region is baked into the member id
405	     * at creation (see the create endpoint), the locality now moves with that identity rather than being
406	     * recomputed from the postcode and city. When an owner has no (well-formed) member id yet (e.g.
407	     * legacy records), fall back to deriving the region directly via {@link #regionOf(Owner)}.
408	     */
409	    default String toLocality(Owner owner) {
410	        String base = memberIdBase(owner.getMemberId());
411	        if (base != null) {
412	            return memberIdRegion(base);
413	        }
414	        return regionOf(owner);
415	    }
416	
417	    /**
418	     * Derive an owner's marketing segment, formatted {@code '<TIER>_<AREA>'} and one of
419	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
420	     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when the owner's membership level (see
421	     * {@link #toMembershipLevel(Owner)}) is 3 or more, otherwise {@code 'STANDARD'}. AREA is
422	     * {@code 'METRO'} when the owner's locality (see {@link #toLocality(Owner)}) is a known region
423	     * (NSW, VIC or QLD, i.e. one carrying a {@link #REGION_TIMEZONE} entry), otherwise
424	     * {@code 'REGIONAL'}.
425	     */
426	    default String toOwnerSegment(Owner owner) {
427	        String tier = toMembershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
428	        String area = REGION_TIMEZONE.containsKey(toLocality(owner)) ? "METRO" : "REGIONAL";
429	        return tier + "_" + area;
430	    }
431	
432	    /**
433	     * Fixed region-to-IANA-timezone table used to derive an owner's timezone: NSW -> Australia/Sydney,
434	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane.
435	     */
436	    Map<String, String> REGION_TIMEZONE = Map.of(
437	        "NSW", "Australia/Sydney",
438	        "VIC", "Australia/Melbourne",
439	        "QLD", "Australia/Brisbane");
440	
441	    /**
442	     * Derive an owner's IANA timezone name from its locality/region (see {@link #toLocality(Owner)})
443	     * via the fixed {@link #REGION_TIMEZONE} table. Returns {@code null} when the region resolves to no
444	     * entry in the table (e.g. 'UNKNOWN'), so the timezone is then absent from the DTO.
445	     */
446	    default String toTimezone(Owner owner) {
447	        return REGION_TIMEZONE.get(toLocality(owner));
448	    }
449	
450	    /**
451	     * Derive an owner's region, preferring the postcode: when the postcode is present and falls within
452	     * a known region's range (see {@link #REGION_POSTCODE_RANGES}) that region wins. When the postcode
453	     * is absent or in no known range, fall back to the fixed {@link #CITY_REGION} table. Returns
454	     * 'UNKNOWN' when neither the postcode nor the city resolves a region. This is the region baked into
455	     * the leading {@code <REGION>} segment of a new owner's member id and, through it, the owner's
456	     * locality.
457	     */
458	    default String regionOf(Owner owner) {
459	        // Prefer the postcode: the region whose range contains it wins. The logic is kept here (rather
460	        // than in a String -> String helper) because MapStruct would treat such a helper as an implicit
461	        // type conversion and wrongly apply it to other String properties (e.g. telephone).
462	        String postcode = owner.getPostcode();
463	        if (postcode != null) {
464	            try {
465	                int value = Integer.parseInt(postcode.trim());
466	                for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
467	                    int[] range = entry.getValue();
468	                    if (value >= range[0] && value <= range[1]) {
469	                        return entry.getKey();
470	                    }
471	                }
472	            }
473	            catch (NumberFormatException ignored) {
474	                // Non-numeric postcode: fall back to the city table below.
475	            }
476	        }
477	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
478	    }
479	
480	    Owner toOwner(OwnerDto ownerDto);
481	
482	    @Mapping(target = "id", ignore = true)
483	    @Mapping(target = "pets", ignore = true)
484	    Owner toOwner(OwnerFieldsDto ownerDto);
485	
486	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
487	
488	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
489	
490	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
491	        OwnerPageDto ownerPageDto = new OwnerPageDto();
492	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
493	        ownerPageDto.setPage(ownerPage.getNumber());
494	        ownerPageDto.setSize(ownerPage.getSize());
495	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
496	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
497	        return ownerPageDto;
498	    }
499	}
